commands.command:
set -eu
if ! getent passwd infraset-nodejs >/dev/null; then sudo useradd --system --home /opt/infraset-nodejs --shell /usr/sbin/nologin infraset-nodejs; fi
sudo install -d -o root -g root -m 0755 /opt/infraset-nodejs
sudo tee /opt/infraset-nodejs/server.js >/dev/null <<'ANTRIEB_NODE_APP'
'use strict';

var http = require('http');
var host = '127.0.0.1';
var port = 3000;

var server = http.createServer(function (request, response) {
  response.writeHead(200, {
    'Content-Type': 'text/plain; charset=utf-8',
    'Content-Length': Buffer.byteLength('infraset-nodejs')
  });
  response.end('infraset-nodejs');
});

server.listen(port, host);
ANTRIEB_NODE_APP
sudo chown root:root /opt/infraset-nodejs/server.js
sudo chmod 0644 /opt/infraset-nodejs/server.js
printf 'app_file_created\n'
